type Payload = { input: string; steps: number; failAttempts: number };

function parsePayload(value: unknown): { payload?: Payload; fields: Array<{ field: string; message: string }> } {
  const fields: Array<{ field: string; message: string }> = [];
  if (!value || typeof value !== 'object' || Array.isArray(value) || Object.getPrototypeOf(value) !== Object.prototype) {
    return { fields: [{ field: 'body', message: 'Must be a JSON object' }] };
  }
  const body = value as Record<string, unknown>;
  for (const key of Object.keys(body)) {
    if (!['input', 'steps', 'failAttempts'].includes(key)) fields.push({ field: key, message: 'Unknown field' });
  }
  if (typeof body.input !== 'string' || body.input.length < 1 || body.input.length > 1000 || body.input.trim() === '') {
    fields.push({ field: 'input', message: 'Must be a non-whitespace string of 1 to 1000 characters' });
  }
  const steps = body.steps === undefined ? 5 : body.steps;
  if (typeof steps !== 'number' || !Number.isInteger(steps) || steps < 1 || steps > 20) {
    fields.push({ field: 'steps', message: 'Must be an integer from 1 to 20' });
  }
  const failAttempts = body.failAttempts === undefined ? 0 : body.failAttempts;
  if (typeof failAttempts !== 'number' || !Number.isInteger(failAttempts) || failAttempts < 0 || failAttempts > 5) {
    fields.push({ field: 'failAttempts', message: 'Must be an integer from 0 to 5' });
  }
  if (fields.length) return { fields };
  return { payload: { input: body.input as string, steps: steps as number, failAttempts: failAttempts as number }, fields };
}

function selectByKey(key: string): JobRow | undefined {
  return db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?').get(key) as JobRow | undefined;
}

function postJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  return (async () => {
    const fields: Array<{ field: string; message: string }> = [];
    const keyHeader = req.headers['idempotency-key'];
    const key = Array.isArray(keyHeader) ? keyHeader[0] : keyHeader;
    if (key !== undefined && !/^[A-Za-z0-9_-]{1,128}$/.test(key)) {
      fields.push({ field: 'Idempotency-Key', message: 'Must contain 1 to 128 letters, numbers, underscores, or hyphens' });
    }
    const contentType = (req.headers['content-type'] ?? '').split(';', 1)[0]!.trim().toLowerCase();
    let parsed: unknown;
    const body = await readBody(req);
    if (contentType !== 'application/json' || body.tooLarge) {
      fields.push({ field: 'body', message: body.tooLarge ? 'Body is too large' : 'Content-Type must be application/json' });
    } else {
      try { parsed = JSON.parse(body.text); }
      catch { fields.push({ field: 'body', message: 'Malformed JSON' }); }
    }
    let payload: Payload | undefined;
    if (contentType === 'application/json' && !body.tooLarge && parsed !== undefined) {
      const validated = parsePayload(parsed);
      payload = validated.payload;
      fields.push(...validated.fields);
    }
    if (fields.length || !payload) {
      invalid(res, fields.length ? fields : [{ field: 'body', message: 'Invalid JSON body' }]);
      return;
    }

    db.exec('BEGIN IMMEDIATE');
    try {
      if (key !== undefined) {
        const existing = selectByKey(key);
        if (existing) {
          db.exec('COMMIT');
          if (existing.input === payload.input && existing.steps === payload.steps && existing.fail_attempts === payload.failAttempts) {
            send(res, 200, rowToJob(existing));
          } else {
            send(res, 409, errorBody('idempotency_conflict', 'Idempotency key was already used with a different payload'));
          }
          return;
        }
      }
      const id = randomUUID();
      const now = nowIso();
      db.prepare(`INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress_completed, idempotency_key, run_after, created_at, updated_at)
        VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, 0, ?, ?)`).run(id, payload.input, payload.steps, payload.failAttempts, key ?? null, now, now);
      const row = db.prepare('SELECT * FROM jobs WHERE id = ?').get(id) as JobRow;
      db.exec('COMMIT');
      send(res, 201, rowToJob(row));
    } catch (error) {
      try { db.exec('ROLLBACK'); } catch { /* transaction already ended */ }
      // A competing server may have inserted the same idempotency key.
      if (key !== undefined && String(error).includes('UNIQUE constraint failed')) {
        const existing = selectByKey(key);
        if (existing) {
          if (existing.input === payload.input && existing.steps === payload.steps && existing.fail_attempts === payload.failAttempts) send(res, 200, rowToJob(existing));
          else send(res, 409, errorBody('idempotency_conflict', 'Idempotency key was already used with a different payload'));
          return;
        }
      }
      throw error;
    }
  })();
}

const port = Number(process.env.PORT ?? 3000);
const server = createServer(async (req, res) => {
  try {
    const { pathname } = new URL(req.url ?? '/', 'http://localhost');
    if (pathname === '/health') {
      if (req.method !== 'GET') return send(res, 405, errorBody('method_not_allowed', 'Method not allowed'));
      const beat = db.prepare('SELECT beat_at FROM heartbeat WHERE id = 1').get() as { beat_at: number } | undefined;
      return send(res, 200, { status: 'ok', worker: beat && Date.now() - beat.beat_at < 3000 ? 'up' : 'down' });
    }
    if (pathname === '/') {
      if (req.method !== 'GET') return send(res, 405, errorBody('method_not_allowed', 'Method not allowed'));
      res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
      res.end(uiHtml);
      return;
    }
    if (pathname === '/api/jobs') {
      if (req.method === 'GET') {
        const rows = db.prepare('SELECT * FROM jobs ORDER BY seq DESC').all() as JobRow[];
        return send(res, 200, { jobs: rows.map(rowToJob) });
      }
      if (req.method === 'POST') return await postJob(req, res);
      return send(res, 405, errorBody('method_not_allowed', 'Method not allowed'));
    }
    const match = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
    if (match) {
      if (req.method !== 'GET') return send(res, 405, errorBody('method_not_allowed', 'Method not allowed'));
      let id: string;
      try { id = decodeURIComponent(match[1]!); }
      catch { return send(res, 404, errorBody('not_found', 'Job not found')); }
      const row = db.prepare('SELECT * FROM jobs WHERE id = ?').get(id) as JobRow | undefined;
      return row ? send(res, 200, rowToJob(row)) : send(res, 404, errorBody('not_found', 'Job not found'));
    }
    return send(res, 404, errorBody('not_found', 'Not found'));
  } catch (error) {
    if (!res.headersSent) send(res, 500, errorBody('internal_error', 'Internal server error'));
    else res.destroy(error instanceof Error ? error : undefined);
  }
});

server.listen(port, () => console.log(`server listening on ${port}`));
let shuttingDown = false;
for (const signal of ['SIGINT', 'SIGTERM'] as const) process.on(signal, () => {
  if (shuttingDown) return;
  shuttingDown = true;
  const fallback = setTimeout(() => process.exit(0), 2000);
  fallback.unref();
  server.close(() => { db.close(); clearTimeout(fallback); process.exit(0); });
  server.closeAllConnections();
});
